"use client";

import { useState } from "react";
import {
  Activity,
  ArrowUpRight,
  Bot,
  ChevronRight,
  CircleDollarSign,
  Command,
  Cpu,
  LayoutDashboard,
  MessageSquare,
  Network,
  Send,
  Settings,
  ShieldCheck,
  Sparkles,
  Wallet,
} from "lucide-react";

const suggestions = [
  "What's happening on Cookie Chain?",
  "Show my COOK balance",
  "Find the best swap for 10 USDC",
];

export default function Home() {
  const [message, setMessage] = useState("");
const [response, setResponse] = useState("");
const [loading, setLoading] = useState(false);

async function sendMessage(text = message) {
  if (!text.trim() || loading) return;

  setLoading(true);
  setResponse("");

  try {
    const res = await fetch("http://localhost:3001/api/chat", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        message: text,
      }),
    });

    const data = await res.json();
    setResponse(data.message ?? data.error ?? "No response");
  } catch {
    setResponse("Unable to reach CookiePilot API.");
  } finally {
    setLoading(false);
  }
}

  return (
    <main className="min-h-screen bg-[#08090c] text-white">
      <div className="flex min-h-screen">
        {/* Sidebar */}
        <aside className="hidden w-64 border-r border-white/10 bg-[#0b0c10] p-5 lg:flex lg:flex-col">
          <div className="mb-10 flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-white text-black">
              <Sparkles size={20} />
            </div>
            <div>
              <div className="font-semibold tracking-tight">CookiePilot</div>
              <div className="text-xs text-white/40">AI on-chain copilot</div>
            </div>
          </div>

          <nav className="space-y-1">
            <NavItem icon={<LayoutDashboard size={18} />} label="Dashboard" active />
            <NavItem icon={<Bot size={18} />} label="AI Agent" />
            <NavItem icon={<Wallet size={18} />} label="Portfolio" />
            <NavItem icon={<Activity size={18} />} label="Activity" />
            <NavItem icon={<Cpu size={18} />} label="Agent Vault" />
          </nav>

          <div className="mt-auto">
            <div className="mb-4 rounded-2xl border border-white/10 bg-white/[0.03] p-4">
              <div className="mb-2 flex items-center gap-2 text-xs text-white/50">
                <Network size={14} />
                Network
              </div>
              <div className="flex items-center gap-2">
                <span className="h-2 w-2 rounded-full bg-emerald-400" />
                <span className="text-sm">Cookie Chain</span>
              </div>
            </div>

            <NavItem icon={<Settings size={18} />} label="Settings" />
          </div>
        </aside>

        {/* Main */}
        <section className="flex-1">
          {/* Header */}
          <header className="flex h-16 items-center justify-between border-b border-white/10 px-5 md:px-8">
            <div className="flex items-center gap-2 text-sm text-white/50">
              <span className="lg:hidden font-semibold text-white">🍪 CookiePilot</span>
              <span className="hidden lg:block">Dashboard</span>
            </div>

            <button className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.04] px-4 py-2 text-sm transition hover:bg-white/[0.08]">
              <Wallet size={16} />
              Connect Nightly
            </button>
          </header>

          <div className="mx-auto max-w-7xl p-5 md:p-8">
            {/* Hero */}
            <div className="mb-8">
              <div className="mb-2 flex items-center gap-2 text-sm text-emerald-400">
                <span className="h-2 w-2 rounded-full bg-emerald-400" />
                Cookie Chain connected
              </div>

              <h1 className="text-3xl font-semibold tracking-tight md:text-4xl">
                Your on-chain command center.
              </h1>

              <p className="mt-2 max-w-2xl text-white/45">
                Ask CookiePilot to analyze your portfolio, explore Cookie Chain,
                or prepare an on-chain transaction.
              </p>
            </div>

            {/* Stats */}
            <div className="mb-8 grid gap-4 md:grid-cols-3">
              <StatCard
                icon={<CircleDollarSign size={18} />}
                label="Portfolio"
                value="$0.00"
                detail="Connect your wallet"
              />

              <StatCard
                icon={<Sparkles size={18} />}
                label="COOK Balance"
                value="—"
                detail="Waiting for wallet"
              />

              <StatCard
                icon={<Activity size={18} />}
                label="Transactions"
                value="0"
                detail="No activity yet"
              />
            </div>

            {/* Agent */}
            <div className="grid gap-6 xl:grid-cols-[1fr_340px]">
              <div className="rounded-3xl border border-white/10 bg-[#0d0f14] p-5 md:p-7">
                <div className="mb-7 flex items-center justify-between">
                  <div>
                    <div className="flex items-center gap-2">
                      <Bot size={19} />
                      <h2 className="font-medium">AI Command Center</h2>
                    </div>
                    <p className="mt-1 text-sm text-white/40">
                      Natural language → MCP → Cookie Chain
                    </p>
                  </div>

                  <div className="hidden items-center gap-2 rounded-lg border border-white/10 px-3 py-1.5 text-xs text-white/40 sm:flex">
                    <Command size={13} />
                    Agent ready
                  </div>
                </div>

                <div className="mb-6 flex min-h-[300px] flex-col rounded-2xl border border-dashed border-white/10 bg-black/10 p-6">
  {!response && !loading ? (
    <div className="flex flex-1 items-center justify-center text-center">
      <div className="max-w-md">
        <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl border border-white/10 bg-white/[0.04]">
          <MessageSquare size={23} className="text-white/60" />
        </div>

        <h3 className="font-medium">What should CookiePilot do?</h3>

        <p className="mt-2 text-sm leading-6 text-white/40">
          Ask about your wallet, Cookie Chain activity, tokens,
          liquidity, or swaps.
        </p>
      </div>
    </div>
  ) : (
    <div className="flex flex-1 flex-col justify-end gap-4">
      <div className="ml-auto max-w-[80%] rounded-2xl bg-white px-4 py-3 text-sm text-black">
        {message}
      </div>

      <div className="max-w-[80%] rounded-2xl border border-white/10 bg-white/[0.04] px-4 py-3 text-sm text-white/70">
        {loading ? "CookiePilot is thinking..." : response}
      </div>
    </div>
  )}
</div>

                <div className="mb-4 flex flex-wrap gap-2">
                  {suggestions.map((suggestion) => (
                    <button
                      key={suggestion}
                      onClick={() => {
  setMessage(suggestion);
  sendMessage(suggestion);
}}
                      className="rounded-xl border border-white/10 bg-white/[0.03] px-3 py-2 text-xs text-white/60 transition hover:bg-white/[0.07] hover:text-white"
                    >
                      {suggestion}
                    </button>
                  ))}
                </div>

                <div className="flex items-center gap-2 rounded-2xl border border-white/10 bg-black/20 p-2">
                  <input
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                    placeholder="Ask CookiePilot..."
                    className="min-w-0 flex-1 bg-transparent px-3 py-3 text-sm outline-none placeholder:text-white/25"
                  />

                  <button
  onClick={() => sendMessage()}
  disabled={loading || !message.trim()}
  className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-white text-black transition hover:bg-white/90 disabled:cursor-not-allowed disabled:opacity-40"
>
  <Send size={17} />
</button>
                </div>
              </div>

              {/* Agent status */}
              <div className="space-y-4">
                <div className="rounded-3xl border border-white/10 bg-[#0d0f14] p-6">
                  <div className="mb-6 flex items-center gap-3">
                    <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-white/[0.06]">
                      <ShieldCheck size={19} />
                    </div>
                    <div>
                      <h3 className="font-medium">Agent Status</h3>
                      <p className="text-xs text-white/40">Operational</p>
                    </div>
                  </div>

                  <StatusRow label="MCP Server" value="Connected" />
                  <StatusRow label="Cookie Chain" value="Online" />
                  <StatusRow label="Wallet" value="Not connected" />
                </div>

                <div className="rounded-3xl border border-white/10 bg-[#0d0f14] p-6">
                  <div className="mb-5 flex items-center justify-between">
                    <div>
                      <h3 className="font-medium">Quick Actions</h3>
                      <p className="text-xs text-white/40">Common operations</p>
                    </div>
                  </div>

                  <QuickAction label="Check chain health" />
                  <QuickAction label="View token markets" />
                  <QuickAction label="Check wallet balance" />
                  <QuickAction label="Prepare a swap" />
                </div>
              </div>
            </div>
          </div>
        </section>
      </div>
    </main>
  );
}

function NavItem({
  icon,
  label,
  active = false,
}: {
  icon: React.ReactNode;
  label: string;
  active?: boolean;
}) {
  return (
    <button
      className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm transition ${
        active
          ? "bg-white text-black"
          : "text-white/45 hover:bg-white/[0.05] hover:text-white"
      }`}
    >
      {icon}
      {label}
    </button>
  );
}

function StatCard({
  icon,
  label,
  value,
  detail,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
  detail: string;
}) {
  return (
    <div className="rounded-2xl border border-white/10 bg-[#0d0f14] p-5">
      <div className="mb-5 flex items-center gap-2 text-white/40">
        {icon}
        <span className="text-sm">{label}</span>
      </div>

      <div className="text-2xl font-semibold">{value}</div>
      <div className="mt-1 text-xs text-white/30">{detail}</div>
    </div>
  );
}

function StatusRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between border-t border-white/[0.06] py-3 text-sm">
      <span className="text-white/40">{label}</span>
      <span className="flex items-center gap-2 text-xs">
        <span
          className={`h-1.5 w-1.5 rounded-full ${
            value === "Not connected" ? "bg-amber-400" : "bg-emerald-400"
          }`}
        />
        {value}
      </span>
    </div>
  );
}

function QuickAction({ label }: { label: string }) {
  return (
    <button className="group flex w-full items-center justify-between border-t border-white/[0.06] py-3 text-left text-sm text-white/60 transition hover:text-white">
      {label}
      <ChevronRight
        size={15}
        className="text-white/20 transition group-hover:translate-x-0.5 group-hover:text-white/60"
      />
    </button>
  );
}
